#include <bits/stdc++.h>
using namespace std;

int n, m, r, c, d, occ[100];
pair<int, int> p[100];

namespace Flow {
    const int N = 10000, M = 20000000;
    int head[N], edge_count, dist[N], parent[N], edge_id[N], source, sink, total_cost;
    struct Edge {
        int to, next, capacity, cost;
    } edges[M];

    void addEdge(int u, int v, int cap, int cst) {
        edges[edge_count].cost = cst;
        edges[edge_count].next = head[u];
        edges[edge_count].to = v;
        edges[edge_count].capacity = cap;
        head[u] = edge_count++;
        edges[edge_count].cost = -cst;
        edges[edge_count].next = head[v];
        edges[edge_count].to = u;
        edges[edge_count].capacity = 0;
        head[v] = edge_count++;
    }

    queue<int> q;
    bool in_queue[N];

    bool bellman_ford() {
        std::fill(dist, dist + N, 0x3f3f3f3f);
        dist[source] = 0;
        q.push(source);
        in_queue[source] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            in_queue[u] = false;
            for (int i = head[u]; i != -1; i = edges[i].next) {
                if (edges[i].capacity == 0) continue;
                if (dist[edges[i].to] > dist[u] + edges[i].cost) {
                    dist[edges[i].to] = dist[u] + edges[i].cost;
                    parent[edges[i].to] = u;
                    edge_id[edges[i].to] = i;
                    if (!in_queue[edges[i].to]) {
                        in_queue[edges[i].to] = true;
                        q.push(edges[i].to);
                    }
                }
            }
        }
        if (dist[sink] == 0x3f3f3f3f) return false;
        int flow = INT_MAX;
        for (int v = sink; v != source; v = parent[v]) {
            flow = min(flow, edges[edge_id[v]].capacity);
        }
        total_cost += dist[sink] * flow;
        for (int v = sink; v != source; v = parent[v]) {
            edges[edge_id[v]].capacity -= flow;
            edges[edge_id[v] ^ 1].capacity += flow;
        }
        return true;
    }
}

using namespace Flow;

int main() {
    scanf("%d%d%d%d%d", &n, &m, &r, &c, &d);
    memset(head, -1, sizeof(head));
    source = (r + n + 1) * n + 1;
    sink = (r + n + 1) * n + 2;
    for (int i = 1, x; i <= r; i++) {
        scanf("%d", &x);
        occ[x]++;
    }
    for (int i = 1; i <= m; i++) {
        scanf("%d%d", &p[i].first, &p[i].second);
    }
    for (int i = 0; i < r + n; i++) {
        for (int j = 1; j <= m; j++) {
            for (int k = 1; k <= r; k++) {
                addEdge(i * n + p[j].first, (i + 1) * n + p[j].second, 1, (2 * k - 1) * d);
                addEdge(i * n + p[j].second, (i + 1) * n + p[j].first, 1, (2 * k - 1) * d);
            }
        }
    }
    for (int i = 1; i <= r + n; i++) {
        addEdge(i * n + 1, sink, INT_MAX, i * c);
        for (int j = 2; j <= n; j++) {
            addEdge((i - 1) * n + j, i * n + j, INT_MAX, 0);
        }
    }
    for (int i = 1; i <= n; i++) {
        addEdge(source, i, occ[i], 0);
    }
    while (bellman_ford());
    printf("%d\n", total_cost);
    return 0;
}
